<script setup>
import PaginationBar from '../../components/PaginationBar.vue'; import { usePaginacion } from '../../composables/usePaginacion.js';
import { computed, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import PageHeader from '../../components/PageHeader.vue'; import AppModal from '../../components/AppModal.vue'; import FormField from '../../components/FormField.vue'; import EmptyState from '../../components/EmptyState.vue';
import { mine, guardarArticulo, moverStock, eliminarArticulo } from '../../services/workshopService.js'; import { get, db } from '../../services/storageService.js'; import { toast, confirmar } from '../../services/uiService.js'; import { tallerId } from '../../services/authService.js';
import { norm, money } from '../../utils/formatters.js'; import { fecha } from '../../utils/dates.js';
const route = useRoute(); const router = useRouter(); const q = ref(''); const bajo = computed(() => route.query.f === 'bajo');
const lista = computed(() => mine('repuestos').filter((s) => (!bajo.value || s.cantidad <= s.minimo) && (!q.value || norm(`${s.nombre} ${s.codigo}`).includes(norm(q.value)))).sort((a, b) => a.nombre.localeCompare(b.nombre)));
const cat = (id) => (get('categorias_repuesto', id) || {}).nombre;
const mod = ref(''); const error = ref(''); const f = reactive({}); let sid = null; const mv = reactive({ tipo: 'entrada', cantidad: 1, nota: '' });
function nuevo(s) { sid = s ? s.id : null; Object.assign(f, { codigo: s?.codigo || '', nombre: s?.nombre || '', categoria: s ? cat(s.categoria_id) : '', marca: s?.marca || '', cantidad: s ? s.cantidad : 0, minimo: s?.minimo ?? 1, costo: s?.costo || '', precio: s?.precio_referencia || '', ubicacion: s?.ubicacion || '' }); error.value = ''; mod.value = 'a'; }
async function borrar(s) { if (!(await confirmar({ mensaje: `¿Eliminar «${s.nombre}» y su historial de movimientos?`, ok: 'Eliminar', cls: 'pel' }))) return; const r = eliminarArticulo(s.id); toast(r.ok ? 'Artículo eliminado.' : r.error, r.ok ? '' : 'error'); }
function guardar() { const r = guardarArticulo(f, sid); if (!r.ok) { error.value = r.error; return; } mod.value = ''; toast('Artículo guardado.'); }
function mover(s) { sid = s.id; Object.assign(mv, { tipo: 'entrada', cantidad: 1, nota: '' }); error.value = ''; mod.value = 'm'; }
function aplicar() { const r = moverStock(sid, mv.tipo, mv.cantidad, mv.nota); if (!r.ok) { error.value = r.error; return; } mod.value = ''; toast('Movimiento registrado.'); }
const movs = computed(() => db.movimientos_stock.filter((m) => { const s = get('repuestos', m.repuesto_id); return s && s.taller_id === tallerId.value; }).slice().reverse());
const pag = usePaginacion(() => lista.value, { reiniciarCon: () => [q.value, bajo.value] });
const pagM = usePaginacion(() => movs.value, { reiniciarCon: () => [movs.value.length === 0] });
</script>
<template>
  <PageHeader titulo="Stock" subtitulo="Repuestos, mínimos y movimientos (nunca queda en negativo)"><button class="btn" type="button" @click="nuevo(null)">Agregar artículo</button></PageHeader>
  <div class="filtros"><div class="campo" style="margin:0"><label>Buscar</label><input v-model="q" placeholder="Nombre o código" /></div><div class="campo" style="margin:0"><label>Mostrar</label><select :value="bajo ? 'bajo' : ''" @change="router.replace({ query: $event.target.value ? { f: 'bajo' } : {} })"><option value="">Todo</option><option value="bajo">Solo stock bajo</option></select></div></div>
  <div v-if="lista.length" class="tabla-wrap"><table class="resp"><thead><tr><th>Código</th><th>Artículo</th><th>Categoría</th><th>Cantidad</th><th>Mínimo</th><th>Costo</th><th></th></tr></thead><tbody>
    <tr v-for="s in pag.items" :key="s.id"><td data-l="Código">{{ s.codigo }}</td><td data-l="Artículo"><b>{{ s.nombre }}</b><br><small>{{ s.ubicacion }}</small></td><td data-l="Categoría">{{ cat(s.categoria_id) }}</td><td data-l="Cantidad"><span class="tag" :class="s.cantidad <= s.minimo ? 't-err' : 't-ok'">{{ s.cantidad }}{{ s.cantidad <= s.minimo ? ' · bajo' : '' }}</span></td><td data-l="Mínimo">{{ s.minimo }}</td><td data-l="Costo">{{ money(s.costo) }}</td><td><button class="btn sec chico" type="button" @click="mover(s)">Entrada / salida</button> <button class="btn sec chico" type="button" @click="nuevo(s)">Editar</button> <button class="btn pel chico" type="button" @click="borrar(s)">Eliminar</button></td></tr></tbody></table></div>
  <PaginationBar v-if="lista.length" :pag="pag" />
  <EmptyState v-else icono="box" titulo="No hay artículos" mensaje="Cambiá el filtro o agregá un artículo." />
  <h2>Historial de movimientos</h2><div v-if="movs.length" class="card tight"><div v-for="m in pagM.items" :key="m.id" class="linea"><span class="f">{{ fecha(m.created_at) }}</span><span style="flex:1">{{ get('repuestos', m.repuesto_id).nombre }} · {{ m.tipo.replace('_', ' ') }} × {{ m.cantidad }} <small>{{ m.nota }}</small></span></div></div><PaginationBar v-if="movs.length" :pag="pagM" /><p v-else class="hint">Todavía no hay movimientos.</p>
  <AppModal v-if="mod === 'a'" titulo="Artículo" @cerrar="mod = ''"><form id="fa" novalidate @submit.prevent="guardar"><div class="form-grid"><FormField v-model="f.codigo" label="Código" req /><FormField v-model="f.nombre" label="Nombre" req /><FormField v-model="f.categoria" label="Categoría" req /><FormField v-model="f.marca" label="Marca" /><FormField v-if="!sid" v-model="f.cantidad" label="Cantidad inicial" type="number" min="0" /><FormField v-model="f.minimo" label="Mínimo" type="number" min="0" /><FormField v-model="f.costo" label="Costo" type="number" min="0" /><FormField v-model="f.precio" label="Precio de referencia" type="number" min="0" /><FormField v-model="f.ubicacion" label="Ubicación" /></div><div class="msg-err" role="alert">{{ error }}</div></form><template #pie><button class="btn sec" type="button" @click="mod = ''">Cancelar</button><button class="btn" type="submit" form="fa">Guardar</button></template></AppModal>
  <AppModal v-if="mod === 'm'" titulo="Movimiento de stock" @cerrar="mod = ''"><form id="fm" novalidate @submit.prevent="aplicar"><FormField v-model="mv.tipo" label="Tipo" type="select" :opciones="[['entrada', 'Entrada'], ['salida', 'Salida']]" /><FormField v-model="mv.cantidad" label="Cantidad" type="number" min="1" /><FormField v-model="mv.nota" label="Nota" /><div class="msg-err" role="alert">{{ error }}</div></form><template #pie><button class="btn sec" type="button" @click="mod = ''">Cancelar</button><button class="btn" type="submit" form="fm">Registrar</button></template></AppModal>
</template>
